import {clsx} from 'clsx'
import {Octicon} from '@primer/react/deprecated'
import {OrganizationIcon, type Icon} from '@primer/octicons-react'
import {testIdProps} from '@github-ui/test-id-props'
import {BorderBox} from './BorderBox'
import styles from './HierarchicalOrgCard.module.css'

interface HierarchicalOrgCardProps {
  title: string
  description?: string
  icon?: Icon
  borderStyle?: 'solid' | 'dashed'
}

export function HierarchicalOrgCard({title, description, icon, borderStyle = 'solid'}: HierarchicalOrgCardProps) {
  const titleOnly = description ? false : true
  return (
    <div className={styles.cardWrapper}>
      <div className={styles.connectorDot} />
      <BorderBox className={styles.contentBox} style={{borderStyle}}>
        <BorderBox {...testIdProps('org-card-icon')} className={styles.iconBox}>
          <Octicon icon={icon || OrganizationIcon} size={16} />
        </BorderBox>
        <div>
          <span
            {...testIdProps('org-card-title')}
            className={clsx(styles.title, titleOnly ? styles.titleMuted : styles.titleDefault)}
          >
            {title}
          </span>
          <span {...testIdProps('org-card-description')} className={styles.description}>
            {description}
          </span>
        </div>
      </BorderBox>
    </div>
  )
}
