import {clsx} from 'clsx'

import styles from './BorderBox.module.css'

interface BorderBoxProps {
  children: React.ReactNode
  className?: string
  style?: React.CSSProperties
}

export function BorderBox({children, className, ...rest}: BorderBoxProps) {
  return (
    <div className={clsx(styles.BorderBox, className)} {...rest}>
      {children}
    </div>
  )
}
